use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserPersonalApiKeyCreatedAtAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserPersonalApiKeyCreatedAtAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getCreatedAt returns null on a freshly created holder.
     */
    public function testCreatedAtNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserPersonalApiKeyCreatedAtAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isCreatedAtAssigned());
        $this->assertNull($holder->getCreatedAt());
    }
}
class ImplWithUserPersonalApiKeyCreatedAtAttributeHolderUnitTest
